    if (!arch_shouldAttach(run)) {
        return true;
    }
    run->netbsd.attachedPid = pid;
    if (!arch_traceAttach(run, pid)) {
        LOG_W("arch_traceAttach(pid=%d) failed", pid);
        kill(pid, SIGKILL);
        /* TODO: missing wait(2)? */
        return false;
    }

    return true;
}

